package com.workworth.earnings.application;
import static org.assertj.core.api.Assertions.assertThat; import static org.mockito.Mockito.*;
import com.workworth.earnings.domain.*; import com.workworth.earnings.persistence.*; import java.math.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.*;
class EarningPeriodServiceTest {WorkdayEarningRepository earnings=mock(WorkdayEarningRepository.class);EarningCorrectionRepository corrections=mock(EarningCorrectionRepository.class); EarningPeriodService service; @BeforeEach void set(){service=new EarningPeriodService(earnings,corrections,Clock.fixed(Instant.parse("2026-01-01T12:00:00Z"),ZoneId.of("Europe/Madrid")),"Europe/Madrid");}
 WorkdayEarning earning(long id,String date,String amount){var e=mock(WorkdayEarning.class);when(e.getId()).thenReturn(id);when(e.getLocalDate()).thenReturn(LocalDate.parse(date));when(e.getStatus()).thenReturn(EarningStatus.AVAILABLE);when(e.getRawAmount()).thenReturn(new BigDecimal(amount));when(e.getCurrencyCode()).thenReturn("EUR");when(corrections.findByEarningIdOrderBySequenceDesc(id)).thenReturn(List.of());return e;}
 @Test void aggregatesTodayWeekMonthAndAllTimeWithOneRounding(){var a=earning(1,"2026-01-01","1.005000000000");var b=earning(2,"2025-12-31","2.005000000000");when(earnings.findAll()).thenReturn(List.of(a,b));assertThat(service.summarize(EarningPeriod.TODAY).publicAmount()).isEqualByComparingTo("1.01");assertThat(service.summarize(EarningPeriod.WEEK).internalAmount()).isEqualByComparingTo("3.010000000000");assertThat(service.summarize(EarningPeriod.MONTH).publicAmount()).isEqualByComparingTo("1.01");assertThat(service.summarize(EarningPeriod.ALL_TIME).publicAmount()).isEqualByComparingTo("3.01");}
 @Test void usesLatestCorrectionAndIgnoresUnavailableAndEmptyHistory(){var a=earning(1,"2025-12-29","10");var correction=mock(EarningCorrection.class);when(correction.getNewAmount()).thenReturn(new BigDecimal("4.500000000000"));when(corrections.findByEarningIdOrderBySequenceDesc(1L)).thenReturn(List.of(correction));var unavailable=mock(WorkdayEarning.class);when(unavailable.getStatus()).thenReturn(EarningStatus.UNAVAILABLE);when(earnings.findAll()).thenReturn(List.of(a,unavailable));assertThat(service.summarize(EarningPeriod.WEEK).publicAmount()).isEqualByComparingTo("4.50");when(earnings.findAll()).thenReturn(List.of());assertThat(service.summarize(EarningPeriod.ALL_TIME).publicAmount()).isZero();}
}
